const items = $input.all();
const maxId = Math.max(...items.map((item) => item?.json?.id));
const newID = maxId + 1;

return { newID };

const items = $input.all();

const labels = items.map((item) => item.json.timestamp);
const data = items.map((item) => item.json.valor);

const chartUrl = `https://quickchart.io/chart?c={type:'line',data:{labels:${JSON.stringify(labels)},datasets:[{data:${JSON.stringify(data)}}]}}`;

return [{ json: { chartUrl }, pairedItem: items.map((_, index) => index) }];
